func TestEnumBaseReportWarningCode(t *testing.T) {
	t.Run("NewFromString_IDENTITY_UNAVAILABLE", func(t *testing.T) {
		t.Parallel()
		val, err := NewBaseReportWarningCodeFromString("IDENTITY_UNAVAILABLE")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, BaseReportWarningCode("IDENTITY_UNAVAILABLE"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_TRANSACTIONS_UNAVAILABLE", func(t *testing.T) {
		t.Parallel()
		val, err := NewBaseReportWarningCodeFromString("TRANSACTIONS_UNAVAILABLE")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, BaseReportWarningCode("TRANSACTIONS_UNAVAILABLE"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_USER_FRAUD_ALERT", func(t *testing.T) {
		t.Parallel()
		val, err := NewBaseReportWarningCodeFromString("USER_FRAUD_ALERT")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, BaseReportWarningCode("USER_FRAUD_ALERT"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewBaseReportWarningCodeFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewBaseReportWarningCodeFromString("IDENTITY_UNAVAILABLE")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

